          <svg class="dl-icon" viewBox="0 0 24 24"><path d="M4 7h16M4 12h16M4 17h16"/></svg>
        </button>
        <button class="dl-drawer-toggle" type="button" title="战术抽屉" data-action="toggle-drawer" aria-label="战术抽屉" aria-expanded="false">
          <svg class="dl-icon" viewBox="0 0 24 24"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6-10-6-10-6Z"/><circle cx="12" cy="12" r="3"/></svg>
          <span class="dl-route-lamp dl-route-idle" data-role="路由灯"></span>
        </button>
      </div>
    </header>
    <section class="dl-holo-layout">
      <nav class="dl-orbital-hub" aria-label="魂核星仪">
        <div class="dl-orbit-ring"></div>
        <div class="dl-orbit-radar"></div>
        <button class="dl-orbit-node dl-node-scene" type="button" data-view-target="环境">环境<span></span></button>
        <button class="dl-orbit-node dl-node-npc" type="button" data-view-target="NPC">NPC<span></span></button>
        <button class="dl-orbit-node dl-node-story" type="button" data-view-target="正文" data-active="true">正文<span></span></button>
        <button class="dl-orbit-node dl-node-review" type="button" data-view-target="推演">推演<span class="dl-node-lamp dl-route-idle" data-role="节点路由灯"></span></button>
        <div class="dl-core"><span>魂</span></div>
      </nav>
      <div class="dl-beam" aria-hidden="true"></div>
      <section class="dl-projection-screen" data-role="投影幕">
        <div class="dl-projection-head">
          <div class="dl-view-title" data-role="视图标题">正文</div>
          <div class="dl-view-state" data-role="视图状态"></div>
        </div>
        <section class="dl-scene-bar" data-role="场景栏"></section>
        <section class="dl-profiles dl-hidden" data-role="档案列"></section>
        <main class="dl-story-flow" data-role="正文流"></main>
        <div class="dl-empty dl-hidden" data-role="空态">未捕获到可渲染内容</div>
      </section>
    </section>
  </div>
  <div class="dl-drawer-backdrop" data-action="close-drawer"></div>
  <aside class="dl-drawer" aria-hidden="true">
    <div class="dl-drawer-head">
      <div class="dl-drawer-title">
        <span class="dl-route-lamp dl-route-idle" data-role="抽屉路由灯"></span>
        <span>DM 战术抽屉</span>
      </div>
      <button class="dl-close-button" type="button" title="关闭" data-action="close-drawer" aria-label="关闭">
        <svg class="dl-icon" viewBox="0 0 24 24"><path d="M18 6 6 18M6 6l12 12"/></svg>
      </button>
    </div>
    <section class="dl-drawer-section" data-role="路由盒"></section>
    <section class="dl-drawer-section" data-role="计划步骤"></section>
    <section class="dl-drawer-section" data-role="审查步骤"></section>
    <section class="dl-drawer-section" data-role="召回折叠"></section>
    <section class="dl-drawer-section" data-role="幕后折叠"></section>
    <section class="dl-drawer-section" data-role="世界账本"></section>
  </aside>
</div>
<script>
(function () {
  'use strict';

  const 主题列表 = ['炫世唐门', '金龙王', '银龙王', '幻海蝶舞'];
  const 主题存储键 = 'lwcs_hanayume_plot_regex_theme_v3';
  const 字号存储键 = 'lwcs_hanayume_plot_regex_font_v3';
  const 密度存储键 = 'lwcs_hanayume_plot_regex_density_v3';
  const 字号列表 = ['0.92', '1', '1.08', '1.16'];
  const 标签列表 = ['scene', 'npc_profile', 'stage', 'act', 'interplay', 'npc_inner', '模块路由', '剧情审查', 'dm_plan', 'recall', 'timeline_recall', '偏差账本召回', 'dmtrack', 'npc_track', 'npc_jump', 'dm_box', 'dm_set'];
  const 空值正则 = /^(?:无|暂无|none|null|n\/a|—|-)$/i;
  const 魂环规则 = [
    ['dl-ring-gold', /大成功|法则|世界书|覆盖|融合技|神级|奇迹|天命/],
    ['dl-ring-red', /重伤|死亡|极危|崩溃|核心冲突|爆发|濒死|血|杀/],
    ['dl-ring-black', /警告|失败|扣除|敌意|战斗|检定|危险|battle|check|惩罚|偏差/],
    ['dl-ring-purple', /关键|推进|支线|核心行动|线索|重要|突破|主线|计划/],
    ['dl-ring-yellow', /轻微|获得|发现|变化|提示|次要|普通物品|调整|召回/],
    ['dl-ring-white', /普通|闲聊|未命中|无变化|日常|无显著/]
  ];

  function 新建(标签, 类名, 文本) {
    const 节点 = document.createElement(标签);
    if (类名) 节点.className = 类名;
    if (文本 !== undefined && 文本 !== null) 节点.textContent = 文本;
    return 节点;
  }

  function 清空(节点) {
    if (节点) 节点.replaceChildren();
  }

  function 读存储(键, 默认值) {
    try {
      return localStorage.getItem(键) || 默认值;
    } catch (错误) {
      return 默认值;
    }
  }

  function 写存储(键, 值) {
    try {
      localStorage.setItem(键, 值);
    } catch (错误) {}
  }

  function 是空内容(内容) {
    const 文本 = String(内容 || '').trim();
    return !文本 || 空值正则.test(文本);
  }

  function 清理文本(文本) {
    return String(文本 || '').replace(/\r\n?/g, '\n').replace(/^[ \t]+$/gm, '').trim();
  }

  function 切行(内容) {
    return 清理文本(内容).split('\n').map(function (行) { return 行.trim(); }).filter(Boolean);
  }

  function 转义正则(文本) {
    return String(文本).replace(/[.*+?^$(){}|[\]\\]/g, function (字符) { return '\\' + 字符; });
  }

  function 解码实体(文本) {
    return String(文本 || '')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&amp;/g, '&')
      .replace(/&#(\d+);/g, function (全词, 数字) { return String.fromCharCode(parseInt(数字, 10)); })
      .replace(/&#x([0-9a-fA-F]+);/g, function (全词, 数字) { return String.fromCharCode(parseInt(数字, 16)); });
  }

  function 解析属性(源码) {
    const 属性 = {};
    const 正则 = /([\u4e00-\u9fa5A-Za-z0-9_:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>]+))/gu;
    let 匹配;
    while ((匹配 = 正则.exec(源码 || ''))) 属性[匹配[1]] = 解码实体(匹配[2] || 匹配[3] || 匹配[4] || '');
    return 属性;
  }

  function 找闭合位置(文本, 标签, 起点) {
    const 名称 = 转义正则(标签);
    const 正则 = new RegExp('</?' + 名称 + '(?:\\s[^<>]*)?>', 'giu');
    正则.lastIndex = 起点;
    let 深度 = 1;
    let 匹配;
    while ((匹配 = 正则.exec(文本))) {
      if (匹配[0].slice(0, 2) === '</') {
        深度 -= 1;
        if (!深度) return { 内容结束: 匹配.index, 结束: 正则.lastIndex };
      } else {
        深度 += 1;
      }
    }
    return null;
  }

  function 扫描标签(文本, 标签) {
    const 结果 = [];
    const 名称 = 转义正则(标签);
    const 正则 = new RegExp('<' + 名称 + '(\\s[^<>]*)?>', 'giu');
    let 匹配;
    while ((匹配 = 正则.exec(文本))) {
      const 内容开始 = 正则.lastIndex;
      const 闭合 = 找闭合位置(文本, 标签, 内容开始);
      if (!闭合) continue;
      结果.push({ 标签: 标签, 属性: 解析属性(匹配[1] || ''), 内容: 文本.slice(内容开始, 闭合.内容结束), 起点: 匹配.index, 终点: 闭合.结束 });
      正则.lastIndex = 闭合.结束;
    }
    return 结果;
  }

  function 找下个子标签(文本, 标签们, 起点) {
    const 名称组 = 标签们.map(转义正则).join('|');
    const 正则 = new RegExp('<(' + 名称组 + ')(\\s[^<>]*)?>', 'giu');
    正则.lastIndex = 起点;
    const 匹配 = 正则.exec(文本);
    if (!匹配) return null;
    return { 标签: 匹配[1], 属性源码: 匹配[2] || '', 起点: 匹配.index, 内容开始: 正则.lastIndex };
  }

  function 拆标签流(文本, 标签们) {
    const 结果 = [];
    let 游标 = 0;
    while (游标 < 文本.length) {
      const 子 = 找下个子标签(文本, 标签们, 游标);
      if (!子) break;
      const 旁白 = 清理文本(文本.slice(游标, 子.起点));
      if (!是空内容(旁白)) 结果.push({ 类型: '旁白', 标签: 'text', 属性: {}, 内容: 旁白, 起点: 游标, 终点: 子.起点 });
      const 闭合 = 找闭合位置(文本, 子.标签, 子.内容开始);
      if (!闭合) {
        游标 = 子.内容开始;
        continue;
      }
      结果.push({ 类型: 子.标签, 标签: 子.标签, 属性: 解析属性(子.属性源码), 内容: 清理文本(文本.slice(子.内容开始, 闭合.内容结束)), 起点: 子.起点, 终点: 闭合.结束 });
      游标 = 闭合.结束;
    }
    const 尾声 = 清理文本(文本.slice(游标));
    if (!是空内容(尾声)) 结果.push({ 类型: '旁白', 标签: 'text', 属性: {}, 内容: 尾声, 起点: 游标, 终点: 文本.length });
    return 结果;
  }

  function 解析文档(原文) {
    const 数据 = { 原文: 原文 };
    for (const 标签 of 标签列表) 数据[标签] = 扫描标签(原文, 标签);
    数据.舞台事件 = [];
    for (const 舞台 of 数据.stage) {
      const 事件们 = 拆标签流(舞台.内容, ['act', 'npc_inner', 'interplay']);
      for (const 事件 of 事件们) 数据.舞台事件.push(事件);
    }
    if (!数据.舞台事件.length) {
      const 独立事件 = [];
      for (const 标签 of ['act', 'interplay']) {
        for (const 项 of 数据[标签]) 独立事件.push({ 类型: 标签, 标签: 标签, 属性: 项.属性, 内容: 清理文本(项.内容), 起点: 项.起点, 终点: 项.终点 });
      }
      独立事件.sort(function (甲, 乙) { return 甲.起点 - 乙.起点; });
      数据.舞台事件 = 独立事件;
    }
    数据.幕后事件 = [];
    for (const 幕后 of 数据.dmtrack) {
      const 事件们 = 拆标签流(幕后.内容, ['scene', 'npc_track', 'npc_jump']);
      for (const 事件 of 事件们) if (事件.标签 !== 'scene') 数据.幕后事件.push(事件);
    }
    return 数据;
  }

  function 取文本列表(数据, 标签) {
    return (数据[标签] || []).map(function (项) { return 清理文本(项.内容); }).filter(function (文本) { return !是空内容(文本); });
  }

  function 取属性(节点, 名称) {
    return 清理文本((节点 && 节点.属性 && 节点.属性[名称]) || '');
  }

  function 找分隔位置(行) {
    const 位置们 = ['：', ':', '＝', '=', '｜', '|'].map(function (符号) { return 行.indexOf(符号); }).filter(function (位置) { return 位置 > 0; });
    if (!位置们.length) return -1;
    return Math.min.apply(null, 位置们);
  }

  function 按行键值(内容) {
    return 切行(内容).map(function (行) {
      const 位置 = 找分隔位置(行);
      if (位置 < 0 || 位置 > 28) return { 键: '', 值: 行 };
      return { 键: 行.slice(0, 位置).trim(), 值: 行.slice(位置 + 1).trim() };
    });
  }

  function 取摘要(内容, 长度) {
    const 第一行 = 切行(内容)[0] || '';
    const 位置 = 找分隔位置(第一行);
    const 文本 = 位置 >= 0 && 位置 <= 18 ? 第一行.slice(位置 + 1).trim() : 第一行;
    return 文本.length > 长度 ? 文本.slice(0, 长度 - 1) + '...' : 文本;
  }

  function 取头像字(名称) {
    return Array.from(String(名称 || '？').trim())[0] || '？';
  }

  function 取魂环类(文本, 默认类) {
    const 内容 = String(文本 || '');
    for (const 规则 of 魂环规则) if (规则[1].test(内容)) return 规则[0];
    return 默认类;
  }

  function 应用魂环(节点, 类名) {
    节点.classList.add(类名 || 'dl-ring-white');
    return 节点;
  }

  function 生成字段组(内容, 高亮台词) {
    const 组 = 新建('div', 'dl-fields');
    const 项们 = 按行键值(内容);
    if (!项们.length) {
      组.appendChild(新建('div', 'dl-field-value', 内容));
      return 组;
    }
    for (const 项 of 项们) {
      if (!项.键) {
        组.appendChild(新建('div', 'dl-field-value', 项.值));
        continue;
      }
      const 行 = 新建('div', 'dl-field-row');
      行.appendChild(新建('div', 'dl-field-name', 项.键));
      const 值 = 新建('div', 'dl-field-value', 项.值);
      if (高亮台词 && /「[^」]+」|"[^"]+"/.test(项.值)) 值.classList.add('dl-dialogue');
      行.appendChild(值);
      组.appendChild(行);
    }
    return 组;
  }

  function 生成场景(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="场景栏"]');
    清空(容器);
    let 数量 = 0;
    for (const 场景 of 数据.scene) {
      for (const 行 of 切行(场景.内容)) {
        const 片段们 = 行.split(/\s*[|｜]\s*/).map(function (项) { return 项.trim(); }).filter(Boolean);
        for (const 片段 of 片段们) {
          容器.appendChild(应用魂环(新建('span', 'dl-scene-chip', 片段), 取魂环类(片段, 'dl-ring-white')));
          数量 += 1;
        }
      }
    }
    return 数量;
  }

  function 设置视图(面板, 名称) {
    const 视图 = ['环境', 'NPC', '正文', '推演'].includes(名称) ? 名称 : '正文';
    面板.dataset.view = 视图;
    for (const 节点 of 面板.querySelectorAll('[data-view-target]')) 节点.dataset.active = 节点.dataset.viewTarget === 视图 ? 'true' : 'false';
    const 标题 = 面板.querySelector('[data-role="视图标题"]');
    if (标题) 标题.textContent = 视图;
    面板.dataset.switching = 'true';
    window.setTimeout(function () {
      if (面板.dataset.view === 视图) delete 面板.dataset.switching;
    }, 220);
    if (视图 === '推演') 设置抽屉(面板, true);
  }

  function 生成档案(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="档案列"]');
    清空(容器);
    if (!数据.npc_profile.length) {
      容器.classList.add('dl-hidden');
      return 0;
    }
    容器.classList.remove('dl-hidden');
    for (const 项 of 数据.npc_profile) {
      const 内容 = 清理文本(项.内容);
      const 名称 = 取属性(项, 'name') || 'NPC';
      const 卡 = 应用魂环(新建('article', 'dl-profile-card'), 取魂环类(内容, 'dl-ring-yellow'));
      卡.tabIndex = 0;
      卡.setAttribute('role', 'button');
      卡.setAttribute('aria-expanded', 'false');
      卡.dataset.open = 'false';
      const 头 = 新建('div', 'dl-profile-head');
      头.appendChild(新建('div', 'dl-avatar', 取头像字(名称)));
      const 名称列 = 新建('div', '');
      名称列.appendChild(新建('div', 'dl-profile-name', 名称));
      const 摘要 = 取摘要(内容, 42);
      if (摘要) 名称列.appendChild(新建('div', 'dl-profile-summary', 摘要));
      头.appendChild(名称列);
      const 详情 = 新建('div', 'dl-profile-detail');
      详情.appendChild(生成字段组(内容, false));
      卡.append(头, 详情);
      容器.appendChild(卡);
    }
    return 数据.npc_profile.length;
  }

  function 生成行动卡(事件) {
    const 内容 = 清理文本(事件.内容);
    const 名称 = 取属性(事件, 'name') || '角色';
    const 卡 = 应用魂环(新建('article', 'dl-card-act'), 取魂环类(内容, 'dl-ring-purple'));
    卡.dataset.name = 名称;
    卡.appendChild(新建('div', 'dl-card-name', 名称));
    卡.appendChild(生成字段组(内容, true));
    return 卡;
  }

  function 生成内心卡(事件) {
    const 内容 = 清理文本(事件.内容);
    const 名称 = 取属性(事件, 'name') || 'NPC';
    const 卡 = 应用魂环(新建('article', 'dl-card-inner'), 取魂环类(内容, 'dl-ring-yellow'));
    卡.dataset.name = 名称;
    卡.appendChild(新建('div', 'dl-card-name', 名称));
    卡.appendChild(生成字段组(内容, false));
    return 卡;
  }

  function 生成旁白卡(内容) {
    const 卡 = 应用魂环(新建('section', 'dl-stage-text'), 取魂环类(内容, 'dl-ring-white'));
    const 正文 = 新建('div', 'dl-stage-body', 清理文本(内容));
    卡.appendChild(正文);
    if (清理文本(内容).length > 220) {
      卡.dataset.collapsed = 'true';
      const 按钮 = 新建('button', 'dl-read-more', '展开');
      按钮.type = 'button';
      按钮.addEventListener('click', function () {
        const 收起 = 卡.dataset.collapsed === 'true';
        卡.dataset.collapsed = 收起 ? 'false' : 'true';
        按钮.textContent = 收起 ? '收起' : '展开';
      });
      卡.appendChild(按钮);
    }
    return 卡;
  }

  function 内心键(事件) {
    return (取属性(事件, 'name') || '') + '\n' + 清理文本(事件.内容);
  }

  function 解析裸舞台字段(文本) {
    const 清理 = 清理文本(文本);
    const 位置 = 找分隔位置(清理);
    if (位置 < 0) return null;
    const 键 = 清理.slice(0, 位置).trim().toLowerCase();
    const 值 = 清理.slice(位置 + 1).trim();
    if (键 === 'interplay') return { 标签: 'interplay', 内容: 值 };
    return null;
  }

  function 生成正文(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="正文流"]');
    清空(容器);
    const 已用内心 = new Set();
    const 内心们 = 数据.npc_inner.map(function (项) { return { 标签: 'npc_inner', 属性: 项.属性, 内容: 清理文本(项.内容), 起点: 项.起点, 终点: 项.终点 }; });
    let 数量 = 0;

    function 取匹配内心(名称) {
      for (const 内心 of 内心们) {
        const 键 = 内心键(内心);
        if (!已用内心.has(键) && 取属性(内心, 'name') === 名称) return 内心;
      }
      return null;
    }

    for (const 事件 of 数据.舞台事件) {
      if (事件.标签 === 'act') {
        const 卡 = 生成行动卡(事件);
        const 内心 = 取匹配内心(取属性(事件, 'name'));
        if (内心) {
          卡.appendChild(生成内心卡(内心));
          已用内心.add(内心键(内心));
          数量 += 1;
        }
        容器.appendChild(卡);
        数量 += 1;
      } else if (事件.标签 === 'npc_inner') {
        const 键 = 内心键(事件);
        if (!已用内心.has(键)) {
          容器.appendChild(生成内心卡(事件));
          已用内心.add(键);
          数量 += 1;
        }
      } else if (事件.标签 === 'interplay') {
        容器.appendChild(生成旁白卡(事件.内容));
        数量 += 1;
      } else if (!是空内容(事件.内容)) {
        const 裸字段 = 解析裸舞台字段(事件.内容);
        容器.appendChild(生成旁白卡(裸字段 ? 裸字段.内容 : 事件.内容));
        数量 += 1;
      }
    }

    for (const 内心 of 内心们) {
      const 键 = 内心键(内心);
      if (已用内心.has(键)) continue;
      容器.appendChild(生成内心卡(内心));
      已用内心.add(键);
      数量 += 1;
    }

    return 数量;
  }

  function 分解步骤(内容) {
    const 步骤 = [];
    const 正则 = /(step\s*\d+[^：:\n]*(?:[：:]|）)?|步骤\s*\d+[^：:\n]*(?:[：:]|）)?|【[^】]+】)/gi;
    let 上次 = 0;
    let 标题 = '';
    let 匹配;
    while ((匹配 = 正则.exec(内容))) {
      const 前文 = 内容.slice(上次, 匹配.index).trim();
      if (前文 || 标题) 步骤.push({ 标题: 标题 || '内容', 内容: 前文 });
      标题 = 匹配[0].replace(/[：:]$/, '').trim();
      上次 = 正则.lastIndex;
    }
    const 收尾 = 内容.slice(上次).trim();
    if (收尾 || 标题) 步骤.push({ 标题: 标题 || '内容', 内容: 收尾 });
    if (!步骤.length) return 切行(内容).map(function (行, 序号) { return { 标题: 'step ' + (序号 + 1), 内容: 行 }; });
    return 步骤;
  }

  function 生成步骤列(标题, 文本们, 默认类) {
    const 列 = 新建('div', 'dl-review-steps');
    let 数量 = 0;
    for (const 文本 of 文本们) {
      for (const 步骤 of 分解步骤(文本)) {
        const 卡 = 应用魂环(新建('div', 'dl-step-item'), 取魂环类(标题 + '\n' + 步骤.标题 + '\n' + 步骤.内容, 默认类 || 'dl-ring-yellow'));
        卡.appendChild(新建('div', 'dl-step-title', 标题 + ' · ' + 步骤.标题));
        if (!是空内容(步骤.内容)) 卡.appendChild(新建('div', 'dl-text-block', 清理文本(步骤.内容)));
        列.appendChild(卡);
        数量 += 1;
      }
    }
    return { 节点: 列, 数量: 数量 };
  }

  function 生成折叠项(标题, 内容, 默认类) {
    const 文本 = 清理文本(内容);
    const 项 = 应用魂环(新建('div', 'dl-accordion-item'), 取魂环类(标题 + '\n' + 文本, 默认类 || 'dl-ring-yellow'));
    项.dataset.open = 'false';
    const 头 = 新建('button', 'dl-accordion-head');
    头.type = 'button';
    头.appendChild(新建('span', '', 标题));
    头.appendChild(新建('span', 'dl-ring-chip', 文本.length + '字'));
    const 体 = 新建('div', 'dl-accordion-body');
    体.appendChild(生成字段组(文本, false));
    头.addEventListener('click', function () {
      项.dataset.open = 项.dataset.open === 'true' ? 'false' : 'true';
    });
    项.append(头, 体);
    return 项;
  }

  function 渲染路由(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="路由盒"]');
    清空(容器);
    const 文本们 = 取文本列表(数据, '模块路由');
    const 合并 = 文本们.join('\n');
    const 命中 = !是空内容(合并) && !/未命中|无/.test(合并);
    for (const 灯 of 面板.querySelectorAll('[data-role="路由灯"], [data-role="抽屉路由灯"], [data-role="节点路由灯"]')) {
      灯.classList.toggle('dl-route-hit', 命中);
      灯.classList.toggle('dl-route-idle', !命中);
    }
    if (!文本们.length) return { 数量: 0, 命中: false };
    容器.appendChild(新建('div', 'dl-drawer-section-title', '模块路由'));
    for (const 文本 of 文本们) {
      const 卡 = 应用魂环(新建('div', 'dl-route-box'), 命中 ? 取魂环类(文本, 'dl-ring-black') : 'dl-ring-white');
      卡.dataset.routeHit = 命中 ? 'true' : 'false';
      卡.appendChild(生成字段组(文本, false));
      容器.appendChild(卡);
    }
    return { 数量: 文本们.length, 命中: 命中 };
  }

  function 渲染计划(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="计划步骤"]');
    清空(容器);
    const 文本们 = 取文本列表(数据, 'dm_plan');
    if (!文本们.length) return 0;
    容器.appendChild(新建('div', 'dl-drawer-section-title', '推进计划'));
    const 结果 = 生成步骤列('推进计划', 文本们, 'dl-ring-purple');
    容器.appendChild(结果.节点);
    return 结果.数量;
  }

  function 渲染审查(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="审查步骤"]');
    清空(容器);
    const 文本们 = 取文本列表(数据, '剧情审查');
    if (!文本们.length) return 0;
    容器.appendChild(新建('div', 'dl-drawer-section-title', '剧情审查'));
    const 结果 = 生成步骤列('剧情审查', 文本们, 'dl-ring-yellow');
    容器.appendChild(结果.节点);
    return 结果.数量;
  }

  function 渲染召回(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="召回折叠"]');
    清空(容器);
    const 条目 = [];
    for (const 标签 of ['recall', 'timeline_recall', '偏差账本召回']) {
      const 文本们 = 取文本列表(数据, 标签);
      for (let 索引 = 0; 索引 < 文本们.length; 索引 += 1) 条目.push([标签 + (文本们.length > 1 ? ' ' + (索引 + 1) : ''), 文本们[索引]]);
    }
    if (!条目.length) return 0;
    容器.appendChild(新建('div', 'dl-drawer-section-title', '召回记录'));
    for (const 条 of 条目) 容器.appendChild(生成折叠项(条[0], 条[1], 条[0].includes('偏差') ? 'dl-ring-black' : 'dl-ring-yellow'));
    return 条目.length;
  }

  function 渲染幕后(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="幕后折叠"]');
    清空(容器);
    const 条目 = [];
    for (const 事件 of 数据.幕后事件) {
      if (事件.标签 === 'npc_track') 条目.push(['npc_track · ' + (取属性(事件, 'name') || 'NPC'), 事件.内容]);
      else if (事件.标签 === 'npc_jump') {
        const 时间 = 取属性(事件, '跃过时间');
        条目.push(['npc_jump · ' + (取属性(事件, 'name') || 'NPC') + (时间 ? ' ' + 时间 : ''), 事件.内容]);
      } else if (!是空内容(事件.内容)) 条目.push(['dmtrack', 事件.内容]);
    }
    if (!条目.length) return 0;
    容器.appendChild(新建('div', 'dl-drawer-section-title', '幕后动向'));
    for (const 条 of 条目) 容器.appendChild(生成折叠项(条[0], 条[1], 'dl-ring-yellow'));
    return 条目.length;
  }

  function 渲染世界账本(面板, 数据) {
    const 容器 = 面板.querySelector('[data-role="世界账本"]');
    清空(容器);
    const 配置 = [
      ['dm_box', 取文本列表(数据, 'dm_box'), 'dl-ring-purple'],
      ['dm_set', 取文本列表(数据, 'dm_set'), 'dl-ring-gold']
    ].filter(function (项) { return 项[1].length; });
    if (!配置.length) return 0;
    容器.appendChild(新建('div', 'dl-drawer-section-title', '世界账本'));
    let 数量 = 0;
    for (const 项 of 配置) {
      for (let 索引 = 0; 索引 < 项[1].length; 索引 += 1) {
        const 标题 = 项[0] + (项[1].length > 1 ? ' ' + (索引 + 1) : '');
        const 卡 = 应用魂环(新建('div', 'dl-world-card'), 取魂环类(标题 + '\n' + 项[1][索引], 项[2]));
        卡.appendChild(新建('div', 'dl-card-title', 标题));
        if (项[0] === 'dm_set') {
          const 结果 = 生成步骤列('dm_set', [项[1][索引]], 'dl-ring-gold');
          卡.appendChild(结果.节点);
        } else {
          卡.appendChild(生成字段组(项[1][索引], false));
        }
        容器.appendChild(卡);
        数量 += 1;
      }
    }
    return 数量;
  }

  function 设置主题(面板, 名称) {
    const 主题 = 主题列表.includes(名称) ? 名称 : 主题列表[0];
    面板.dataset.theme = 主题;
    for (const 按钮 of 面板.querySelectorAll('[data-theme-name]')) 按钮.setAttribute('aria-pressed', 按钮.dataset.themeName === 主题 ? 'true' : 'false');
    写存储(主题存储键, 主题);
  }

  function 设置字号(面板, 值) {
    const 字号 = 字号列表.includes(String(值)) ? String(值) : '1';
    面板.style.setProperty('--字号倍率', 字号);
    写存储(字号存储键, 字号);
  }

  function 切换字号(面板) {
    const 当前 = getComputedStyle(面板).getPropertyValue('--字号倍率').trim() || '1';
    const 序号 = 字号列表.indexOf(当前);
    设置字号(面板, 字号列表[(序号 + 1) % 字号列表.length]);
  }

  function 设置密度(面板, 值) {
    const 密度 = 值 === '紧凑' ? '紧凑' : '标准';
    面板.dataset.density = 密度;
    写存储(密度存储键, 密度);
  }

  function 切换密度(面板) {
    设置密度(面板, 面板.dataset.density === '紧凑' ? '标准' : '紧凑');
  }

  function 设置抽屉(面板, 打开) {
    const 按钮 = 面板.querySelector('[data-action="toggle-drawer"]');
    const 抽屉 = 面板.querySelector('.dl-drawer');
    if (!打开 && 抽屉 && 抽屉.contains(document.activeElement) && 按钮) 按钮.focus();
    面板.classList.toggle('is-drawer-open', 打开);
    if (按钮) 按钮.setAttribute('aria-expanded', 打开 ? 'true' : 'false');
    if (抽屉) 抽屉.setAttribute('aria-hidden', 打开 ? 'false' : 'true');
  }

  function 切换档案(卡) {
    const 列 = 卡.closest('[data-role="档案列"]');
    const 打开 = 卡.dataset.open === 'true';
    if (列) {
      for (const 同级 of 列.querySelectorAll('.dl-profile-card')) {
        同级.dataset.open = 'false';
        同级.setAttribute('aria-expanded', 'false');
      }
    }
    卡.dataset.open = 打开 ? 'false' : 'true';
    卡.setAttribute('aria-expanded', 打开 ? 'false' : 'true');
  }

  function 更新统计(面板, 数据, 统计) {
    const 人物 = new Set();
    const 收 = function (名称) { if (!是空内容(名称)) 人物.add(清理文本(名称)); };
    for (const 项 of 数据.npc_profile) 收(取属性(项, 'name'));
    for (const 项 of 数据.act) 收(取属性(项, 'name'));
    for (const 项 of 数据.npc_inner) 收(取属性(项, 'name'));
    for (const 项 of 数据.npc_track) 收(取属性(项, 'name'));
    for (const 项 of 数据.npc_jump) 收(取属性(项, 'name'));
    const 节点 = 面板.querySelector('[data-role="统计"]');
    if (节点) 节点.textContent = '场景 ' + 数据.scene.length + ' / NPC ' + 人物.size + ' / 召回 ' + 统计.召回 + ' / 数据 ' + 统计.数据;
    const 视图状态 = 面板.querySelector('[data-role="视图状态"]');
    if (视图状态) 视图状态.textContent = '档案 ' + 数据.npc_profile.length + ' / 正文 ' + 统计.正文 + ' / 推演 ' + 统计.数据;
  }

  function 绑定交互(面板) {
    设置主题(面板, 读存储(主题存储键, 主题列表[0]));
    设置字号(面板, 读存储(字号存储键, '1'));
    设置密度(面板, 读存储(密度存储键, '标准'));

    面板.addEventListener('click', function (事件) {
      const 视图节点 = 事件.target.closest('[data-view-target]');
      if (视图节点 && 面板.contains(视图节点)) {
        设置视图(面板, 视图节点.dataset.viewTarget);
        return;
      }
      const 主题按钮 = 事件.target.closest('[data-theme-name]');
      if (主题按钮 && 面板.contains(主题按钮)) {
        设置主题(面板, 主题按钮.dataset.themeName);
        return;
      }
      const 动作按钮 = 事件.target.closest('[data-action]');
      if (动作按钮 && 面板.contains(动作按钮)) {
        if (动作按钮.dataset.action === 'font') 切换字号(面板);
        if (动作按钮.dataset.action === 'density') 切换密度(面板);
        if (动作按钮.dataset.action === 'toggle-drawer') 设置抽屉(面板, !面板.classList.contains('is-drawer-open'));
        if (动作按钮.dataset.action === 'close-drawer') 设置抽屉(面板, false);
        return;
      }
      const 档案卡 = 事件.target.closest('.dl-profile-card');
      if (档案卡 && 面板.contains(档案卡)) 切换档案(档案卡);
    });

    面板.addEventListener('keydown', function (事件) {
      const 视图节点 = 事件.target.closest('[data-view-target]');
      if (视图节点 && 面板.contains(视图节点) && (事件.key === 'Enter' || 事件.key === ' ')) {
        事件.preventDefault();
        设置视图(面板, 视图节点.dataset.viewTarget);
        return;
      }
      const 档案卡 = 事件.target.closest('.dl-profile-card');
      if (!档案卡 || !面板.contains(档案卡) || (事件.key !== 'Enter' && 事件.key !== ' ')) return;
      事件.preventDefault();
      切换档案(档案卡);
    });
  }

  function 启动(面板) {
    if (面板.dataset.initialized === 'true') return;
    面板.dataset.initialized = 'true';
    const 原文 = 面板.querySelector('.dl-buffer') ? 面板.querySelector('.dl-buffer').value : '';
    const 数据 = 解析文档(原文);
    绑定交互(面板);
    const 场景数 = 生成场景(面板, 数据);
    const 档案数 = 生成档案(面板, 数据);
    const 正文数 = 生成正文(面板, 数据);
    const 路由 = 渲染路由(面板, 数据);
    const 计划数 = 渲染计划(面板, 数据);
    const 审查数 = 渲染审查(面板, 数据);
    const 召回数 = 渲染召回(面板, 数据);
    const 幕后数 = 渲染幕后(面板, 数据);
    const 账本数 = 渲染世界账本(面板, 数据);
    const 数据数 = 路由.数量 + 计划数 + 审查数 + 召回数 + 幕后数 + 账本数;
    更新统计(面板, 数据, { 正文: 正文数, 召回: 召回数, 数据: 数据数 });
    const 空态 = 面板.querySelector('[data-role="空态"]');
    if (空态 && !场景数 && !档案数 && !正文数 && !数据数) 空态.classList.remove('dl-hidden');
    设置视图(面板, '正文');
  }

  for (const 面板 of document.querySelectorAll('.dl-panel')) 启动(面板);
})();
</script>
</html>
